123→// ─── Loader ───────────────────────────────────────────────────────────────────
124→
125→export const loader = async ({ request }: LoaderFunctionArgs) => {
126→  const { session, billing } = await authenticate.admin(request);
127→  const shop = session.shop;
128→
129→  try {
130→    /* eslint-disable @typescript-eslint/no-explicit-any */
131→    const billingCheck = await billing.check({
132→      plans: ALL_PAID_PLANS as any,
133→      isTest: process.env.NODE_ENV !== "production",
134→    });
135→    /* eslint-enable @typescript-eslint/no-explicit-any */
136→    const subscription = await syncSubscriptionFromShopify(
137→      shop,
138→      billingCheck.appSubscriptions ?? [],
139→    );
140→    return { subscription };
141→  } catch {
142→    const subscription = await getShopSubscription(shop);
143→    return { subscription };
144→  }
145→};
146→
147→// ─── Action ───────────────────────────────────────────────────────────────────
148→
149→export const action = async ({ request }: ActionFunctionArgs): Promise<
150→  | { error: string }
151→  | { success: boolean; message: string }
152→  | null
153→> => {
154→  const { session, billing } = await authenticate.admin(request);
155→  const shop = session.shop;
156→  const formData = await request.formData();
157→  const intent = String(formData.get("intent"));
158→
159→  if (intent === "subscribe") {
160→    const plan = String(formData.get("plan"));
161→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
162→    try {
163→      /* eslint-disable @typescript-eslint/no-explicit-any */
164→      // billing.request() throws a redirect Response to Shopify's
165→      // billing confirmation page — we must let it propagate.
166→      await billing.request({
167→        plan: plan as any,
168→        isTest: process.env.NODE_ENV !== "production",
169→        returnUrl,
170→      });
171→      /* eslint-enable @typescript-eslint/no-explicit-any */
172→      return null;
173→    } catch (error) {
174→      // Re-throw Response redirects so React Router / App Bridge handles them
175→      if (error instanceof Response) throw error;
176→      // BillingError has errorData with Shopify userErrors
177→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
178→      console.error("Billing error:", error);
179→      console.error("Billing errorData:", JSON.stringify(errorData, null, 2));
180→      const details = errorData?.map((e) => e.message).join(", ");
181→      const message = details || (error instanceof Error ? error.message : String(error));
182→
183→      // Provide a helpful message for common billing errors
184→      if (message.includes("Custom apps cannot use the Billing API")) {
185→        return {
186→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
187→        };
188→      }
189→      return {
190→        error: `Failed to initiate subscription: ${message}`,
191→      };
192→    }
193→  }
194→
195→  if (intent === "cancel") {
196→    try {
197→      const sub = await getShopSubscription(shop);
198→      if (sub.shopifySubscriptionId) {
199→        await billing.cancel({
200→          subscriptionId: sub.shopifySubscriptionId,
201→          isTest: process.env.NODE_ENV !== "production",
202→          prorate: true,
203→        });
204→      }
205→      await cancelShopSubscription(shop);
206→      return {
207→        success: true,
208→        message: "Subscription cancelled. You are now on the Free plan.",
209→      };
210→    } catch {
211→      return { error: "Failed to cancel subscription. Please try again." };
212→    }
213→  }
214→
215→  return null;
216→};
