233→// ─── Plan card ────────────────────────────────────────────────────────────────
234→
235→type PlanCardProps = {
236→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
237→  isAnnual: boolean;
238→  currentTier: string;
239→  onSubscribe: (planName: string) => void;
240→  onRequestCancel: () => void;
241→  loadingPlan: string | null;
242→};
243→
244→function PlanCard({
245→  plan,
246→  isAnnual,
247→  currentTier,
248→  onSubscribe,
249→  onRequestCancel,
250→  loadingPlan,
251→}: PlanCardProps) {
252→  const isCurrent = currentTier === plan.id;
253→  const isBestValue = "bestValue" in plan && plan.bestValue;
254→  const isCurrentPaid = currentTier !== "free";
255→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
256→
257→  const TIER_ORDER: Record<string, number> = {
258→    free: 0,
259→    starter: 1,
260→    pro: 2,
261→    ultimate: 3,
262→  };
263→  const isUpgrade =
264→    !isCurrent &&
265→    plan.id !== "free" &&
266→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
267→
268→  const shopifyPlan = isAnnual
269→    ? plan.shopifyPlanAnnual
270→    : plan.shopifyPlanMonthly;
271→
272→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
273→
274→  let buttonContent = "Start 7-day free trial";
275→  if (isCurrent) {
276→    buttonContent = "Current plan";
277→  } else if (isDowngradeToFree) {
278→    buttonContent = "Downgrade to Free";
279→  } else if (isUpgrade) {
280→    buttonContent = `Upgrade to ${plan.name}`;
281→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
282→    buttonContent = `Switch to ${plan.name}`;
283→  }
284→
285→  const handleClick = () => {
286→    if (isCurrent) return;
287→    if (isDowngradeToFree) {
288→      onRequestCancel();
289→    } else if (shopifyPlan) {
290→      onSubscribe(shopifyPlan);
291→    }
292→  };
293→
294→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
295→
296→  return (
297→    <Card>
298→      <BlockStack gap="400">
299→
300→        {/* Plan name + badges */}
301→        <BlockStack gap="100">
302→          <InlineStack align="space-between" blockAlign="center">
303→            <Text as="h3" variant="headingMd" fontWeight="bold">
304→              {plan.name}
305→            </Text>
306→            <InlineStack gap="150">
307→              {isBestValue && (
308→                <Badge tone="info" icon={StarIcon}>
309→                  Most popular
310→                </Badge>
311→              )}
312→              {isCurrent && <Badge tone="success">Active</Badge>}
313→            </InlineStack>
314→          </InlineStack>
315→          <Text as="p" variant="bodySm" tone="subdued">
316→            {plan.description}
317→          </Text>
318→        </BlockStack>
319→
320→        <Divider />
321→
322→        {/* Price */}
323→        <BlockStack gap="100">
324→          {plan.monthlyPrice === 0 ? (
325→            <>
326→              <Text as="p" variant="headingXl" fontWeight="bold">
327→                Free
328→              </Text>
329→              <Text as="p" variant="bodySm" tone="subdued">
330→                forever
331→              </Text>
332→            </>
333→          ) : (
334→            <>
335→              <InlineStack gap="100" blockAlign="baseline">
336→                <Text as="p" variant="headingXl" fontWeight="bold">
337→                  ${displayPrice}
338→                </Text>
339→                <Text as="p" variant="bodySm" tone="subdued">
340→                  / month
341→                </Text>
342→              </InlineStack>
343→              <Text as="p" variant="bodySm" tone="subdued">
344→                {isAnnual
345→                  ? `billed $${plan.annualPrice} / year`
346→                  : `or $${plan.annualMonthlyPrice}/mo billed annually`}
347→              </Text>
348→            </>
349→          )}
350→        </BlockStack>
351→
352→        {/* CTA button */}
353→        <Button
354→          variant={isCurrent ? "secondary" : "primary"}
355→          tone={isDowngradeToFree ? "critical" : undefined}
356→          onClick={handleClick}
357→          disabled={isCurrent}
358→          loading={isThisLoading}
359→          fullWidth
360→        >
361→          {buttonContent}
362→        </Button>
363→
364→        <Divider />
365→
366→        {/* Features list */}
367→        <BlockStack gap="300">
368→          {plan.features.map((f) => (
369→            <PlanFeature key={f} feature={f} />
370→          ))}
371→        </BlockStack>
372→
373→      </BlockStack>
374→    </Card>
375→  );
376→}
