380→export default function PricingPage() {
381→  const { subscription } = useLoaderData<typeof loader>();
382→  const fetcher = useFetcher<typeof action>();
383→  const shopify = useAppBridge();
384→
385→  const [isAnnual, setIsAnnual] = useState(
386→    subscription.billingInterval === "annual",
387→  );
388→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
389→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
390→
391→  const data = fetcher.data;
392→  const isFetching = fetcher.state !== "idle";
393→
394→  // Toast notifications + clear loading state
395→  useEffect(() => {
396→    if (!isFetching) setLoadingPlan(null);
397→    if (data && "message" in data && data.message) {
398→      shopify.toast.show(data.message as string);
399→    }
400→    if (data && "error" in data && data.error) {
401→      shopify.toast.show(data.error as string, { isError: true });
402→    }
403→  }, [data, isFetching, shopify]);
404→
405→  const handleSubscribe = useCallback(
406→    (planName: string) => {
407→      setLoadingPlan(planName);
408→      const fd = new FormData();
409→      fd.set("intent", "subscribe");
410→      fd.set("plan", planName);
411→      fetcher.submit(fd, { method: "POST" });
412→    },
413→    [fetcher],
414→  );
415→
416→  const handleConfirmCancel = useCallback(() => {
417→    setCancelModalOpen(false);
418→    setLoadingPlan("cancel");
419→    const fd = new FormData();
420→    fd.set("intent", "cancel");
421→    fetcher.submit(fd, { method: "POST" });
422→  }, [fetcher]);
423→
424→  const currentTier = subscription.planTier;
425→  const currentPlanName =
426→    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";
427→
428→  // Suggest next tier for upgrade banner
429→  const nextTier =
430→    currentTier === "free"
431→      ? "starter"
432→      : currentTier === "starter"
433→        ? "pro"
434→        : null;
435→
436→  return (
437→    <Page
438→      title="Pricing"
439→      subtitle="Choose the plan that's right for your store"
440→      backAction={{ url: "/app" }}
441→    >
442→      <Box paddingBlockEnd="1600">
443→      <Layout>
444→        <Layout.Section>
445→          <BlockStack gap="600">
446→
447→            {/* Current plan status */}
448→            {nextTier ? (
449→              <Banner
450→                tone="info"
451→                title={`You're on the ${currentPlanName} plan`}
452→                action={{
453→                  content: `Upgrade to ${PLANS_DATA[nextTier].name}`,
454→                  onAction: () => {
455→                    const plan = isAnnual
456→                      ? PLANS_DATA[nextTier].shopifyPlanAnnual
457→                      : PLANS_DATA[nextTier].shopifyPlanMonthly;
458→                    if (plan) handleSubscribe(plan);
459→                  },
460→                }}
461→              >
462→                <Text as="p" variant="bodyMd">
463→                  {currentTier === "free"
464→                    ? "You have up to 20 allowed zip codes and basic widget access. Upgrade to unlock more features."
465→                    : "Upgrade to Pro for unlimited zip codes, blocked areas, full waitlist, and more."}
466→                </Text>
467→              </Banner>
468→            ) : (
469→              <Banner tone="success" title={`You're on the ${currentPlanName} plan`}>
470→                <InlineStack gap="200" blockAlign="center">
471→                  <Badge tone="success">Active</Badge>
472→                  <Text as="p" variant="bodyMd">
473→                    {currentTier === "ultimate"
474→                      ? "You have full access to all features including VIP support and API access."
475→                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
476→                  </Text>
477→                </InlineStack>
478→              </Banner>
479→            )}
480→
481→            {/* Action feedback banners */}
482→            {data && "error" in data && data.error && (
483→              <Banner tone="critical">{String(data.error)}</Banner>
484→            )}
485→            {data && "success" in data && data.success && (
486→              <Banner tone="success">
487→                {data && "message" in data
488→                  ? String(data.message)
489→                  : "Plan updated successfully."}
490→              </Banner>
491→            )}
492→
493→            {/* Billing toggle */}
494→            <BlockStack gap="200" inlineAlign="center">
495→              <ButtonGroup variant="segmented">
496→                <Button
497→                  pressed={!isAnnual}
498→                  onClick={() => setIsAnnual(false)}
499→                >
500→                  Monthly
501→                </Button>
502→                <Button
503→                  pressed={isAnnual}
504→                  onClick={() => setIsAnnual(true)}
505→                >
506→                  Annual · Save up to 38%
507→                </Button>
508→              </ButtonGroup>
509→              {isAnnual && (
510→                <Badge tone="success">You save up to 38% per year</Badge>
511→              )}
512→            </BlockStack>
513→
514→            {/* Plan cards — 4 columns */}
515→            <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
516→              {(
517→                Object.values(
518→                  PLANS_DATA,
519→                ) as (typeof PLANS_DATA)[keyof typeof PLANS_DATA][]
520→              ).map((plan) => (
521→                <PlanCard
522→                  key={plan.id}
523→                  plan={plan}
524→                  isAnnual={isAnnual}
525→                  currentTier={currentTier}
526→                  onSubscribe={handleSubscribe}
527→                  onRequestCancel={() => setCancelModalOpen(true)}
528→                  loadingPlan={loadingPlan}
529→                />
530→              ))}
531→            </InlineGrid>
532→
533→            {/* Trial footnote */}
534→            {(currentTier === "free" || currentTier === "starter") && (
535→              <Text
536→                as="p"
537→                variant="bodySm"
538→                tone="subdued"
539→                alignment="center"
540→              >
541→                All paid plans include a 7-day free trial. No credit card
542→                charged until the trial ends.
543→              </Text>
544→            )}
545→
546→          </BlockStack>
547→        </Layout.Section>
548→      </Layout>
549→      </Box>
550→
551→      {/* Downgrade confirmation modal */}
552→      <Modal
553→        open={cancelModalOpen}
554→        onClose={() => setCancelModalOpen(false)}
555→        title="Downgrade to Free plan?"
556→        primaryAction={{
557→          content: "Yes, downgrade",
558→          destructive: true,
559→          onAction: handleConfirmCancel,
560→          loading: loadingPlan === "cancel",
561→        }}
562→        secondaryActions={[
563→          {
564→            content: "Keep current plan",
565→            onAction: () => setCancelModalOpen(false),
566→          },
567→        ]}
568→      >
569→        <Modal.Section>
570→          <BlockStack gap="400">
571→            <Text as="p" variant="bodyMd">
572→              Downgrading to Free will immediately remove access to:
573→            </Text>
574→            <BlockStack gap="200">
575→              {[
576→                "Unlimited zip codes — limited to 20",
577→                "Blocked zip codes",
578→                "Delivery rules, zones & ETAs",
579→                "Bulk CSV import & export",
580→                "Customer waitlist",
581→                "Widget customization (colors, position)",
582→                "Cart & checkout blocking",
583→              ].map((item) => (
584→                <InlineStack key={item} gap="200" blockAlign="start" wrap={false}>
585→                  <Text as="span" variant="bodyMd" tone="subdued">·</Text>
586→                  <Text as="p" variant="bodyMd">{item}</Text>
587→                </InlineStack>
588→              ))}
589→            </BlockStack>
590→            <Banner tone="warning">
591→              <Text as="p" variant="bodyMd">
592→                Zip codes over the 20-entry limit will remain saved but become
593→                inactive until you upgrade again.
594→              </Text>
595→            </Banner>
596→          </BlockStack>
597→        </Modal.Section>
598→      </Modal>
599→    </Page>
600→  );
601→}
