  1→/**
  2→ * Public API endpoint for the storefront zip code widget.
  3→ *
  4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
  5→ * to check whether a zip code is serviceable.
  6→ *
  7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
  8→ *
  9→ * Response:
 10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
 11→ *   200 { allowed: false, message: "..." }
 12→ *   400 { error: "Missing shop or zip parameter" }
 13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
 14→ */
 15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→
 18→/**
 19→ * Normalize postal/zip code for multi-format international support.
 20→ * Handles: US ZIP+4, UK postcodes, Indian pincodes, Australian postcodes, Canadian postal codes.
 21→ */
 22→function normalizeZipCode(raw: string): string {
 23→  let z = raw.trim().toUpperCase();
 24→  z = z.replace(/\s+/g, "");        // collapse all internal spaces (UK: SW1A 2AA → SW1A2AA)
 25→  z = z.replace(/-\d{4}$/, "");     // strip US ZIP+4 suffix (90210-1234 → 90210)
 26→  return z;
 27→}
 28→
 29→const CORS_HEADERS = {
 30→  "Access-Control-Allow-Origin": "*",
 31→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
 32→  "Access-Control-Allow-Headers": "Content-Type",
 33→  "Content-Type": "application/json",
 34→};
 35→
 36→// Applied only to successful ZIP check responses (200) to reduce DB load
 37→// for repeated lookups of the same ZIP code from the same storefront visitor.
 38→const SUCCESS_HEADERS = {
 39→  ...CORS_HEADERS,
 40→  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
 41→};
 42→
 43→const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
 44→
 45→async function handleZipCheck(shop: string | null, zip: string | null) {
 46→  if (!shop || !zip) {
 47→    return new Response(
 48→      JSON.stringify({ error: "Missing shop or zip parameter" }),
 49→      { status: 400, headers: CORS_HEADERS },
 50→    );
 51→  }
 52→
 53→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 54→  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
 55→    return new Response(
 56→      JSON.stringify({ error: "Invalid shop parameter" }),
 57→      { status: 400, headers: CORS_HEADERS },
 58→    );
 59→  }
 60→
 61→  // Enforce input length limits to prevent abuse
 62→  if (zip.length > 20) {
 63→    return new Response(
 64→      JSON.stringify({ error: "Invalid zip code" }),
 65→      { status: 400, headers: CORS_HEADERS },
 66→    );
 67→  }
 68→
 69→  const normalizedZip = normalizeZipCode(zip);
 70→
 71→  const zipRecord = await db.zipCode.findUnique({
 72→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
 73→  });
 74→
 75→  // Fetch widget config for custom messages (falls back to defaults)
 76→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
 77→
 78→  // Fetch shop settings to determine default behavior for unlisted zip codes
 79→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
 80→  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
 81→
 82→  if (!zipRecord || !zipRecord.isActive) {
 83→    const notFoundMsg =
 84→      widgetConfig?.notFoundMessage ??
 85→      "This zip code was not found in our system.";
 86→
 87→    // If the zip is simply not in the list (not inactive) and the merchant
 88→    // has set defaultBehavior to "allow", treat it as an allowed zip
 89→    if (!zipRecord && defaultBehavior === "allow") {
 90→      const successMsg =
 91→        widgetConfig?.successMessage ?? "We deliver to your area!";
 92→      return new Response(
 93→        JSON.stringify({
 94→          allowed: true,
 95→          message: successMsg,
 96→          eta: null,
 97→          zone: null,
 98→          codAvailable: null,
 99→          returnPolicy: null,
100→          showWaitlist: false,
101→          waitlistCount: 0,
102→          cutoffTime: null,
103→          daysOfWeek: null,
104→        }),
105→        { status: 200, headers: SUCCESS_HEADERS },
106→      );
107→    }
108→
109→    // Social proof: count how many customers are waiting for this ZIP
110→    let waitlistCount = 0;
111→    try {
112→      waitlistCount = await db.waitlistEntry.count({
113→        where: { shop, zipCode: normalizedZip, status: "waiting" },
114→      });
115→    } catch {
116→      waitlistCount = 0;
117→    }
118→
119→    if (!zipRecord) {
120→      return new Response(
121→        JSON.stringify({
122→          allowed: false,
123→          message: notFoundMsg,
124→          notFound: true,
125→          showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
126→          waitlistCount,
127→        }),
128→        { status: 200, headers: SUCCESS_HEADERS },
129→      );
130→    }
131→
132→    // Inactive zip — treat same as not found regardless of defaultBehavior
133→    return new Response(
134→      JSON.stringify({
135→        allowed: false,
136→        message: notFoundMsg,
137→        notFound: true,
138→        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
139→        waitlistCount,
140→      }),
141→      { status: 200, headers: SUCCESS_HEADERS },
142→    );
143→  }
144→
145→  if (zipRecord.type === "blocked") {
146→    const errorMsg =
147→      zipRecord.message ??
148→      widgetConfig?.errorMessage ??
149→      "Sorry, we don't deliver to this area yet.";
150→
151→    // Social proof: count how many customers are waiting for this ZIP
152→    let waitlistCount = 0;
153→    try {
154→      waitlistCount = await db.waitlistEntry.count({
155→        where: { shop, zipCode: normalizedZip, status: "waiting" },
156→      });
157→    } catch {
158→      waitlistCount = 0;
159→    }
160→
161→    return new Response(
162→      JSON.stringify({
163→        allowed: false,
164→        message: errorMsg,
165→        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
166→        waitlistCount,
167→      }),
168→      { status: 200, headers: SUCCESS_HEADERS },
169→    );
170→  }
171→
172→  // Fetch the most relevant active DeliveryRule for this zip.
173→  // Priority 1: rules that explicitly list this zip in their zipCodes field.
174→  // Priority 2: rules that match by zone (with no explicit zip list).
175→  // Within each priority tier, order by `priority ASC` (lower = higher priority).
176→  const zipCodeUpper = normalizedZip;
177→  const zipZone = zipRecord.zone ?? null;
178→
179→  // Fetch all active rules for the shop ordered by priority so we can apply
180→  // the matching logic in a single query result.
181→  const activeRules = await db.deliveryRule.findMany({
182→    where: { shop, isActive: true },
183→    orderBy: { priority: "asc" },
184→  });
185→
186→  let matchedRule: (typeof activeRules)[number] | null = null;
187→
188→  // Pass 1: explicit zip match — zipCodes field contains this zip code
189→  for (const rule of activeRules) {
190→    if (rule.zipCodes) {
191→      const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
192→      if (zips.includes(zipCodeUpper)) {
193→        matchedRule = rule;
194→        break;
195→      }
196→    }
197→  }
198→
199→  // Pass 2: zone match — rule's zone matches the zip's zone and no explicit zip list
200→  if (!matchedRule && zipZone) {
201→    for (const rule of activeRules) {
202→      if (
203→        rule.zone === zipZone &&
204→        (!rule.zipCodes || rule.zipCodes.trim() === "")
205→      ) {
206→        matchedRule = rule;
207→        break;
208→      }
209→    }
210→  }
211→
212→  // Allowed
213→  const successMsg =
214→    zipRecord.message ??
215→    widgetConfig?.successMessage ??
216→    "Great news! We deliver to your area.";
217→
218→  return new Response(
219→    JSON.stringify({
220→      allowed: true,
221→      message: successMsg,
222→      eta: widgetConfig?.showEta ? (zipRecord.eta ?? null) : null,
223→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
224→      codAvailable: widgetConfig?.showCod !== false ? (zipRecord.codAvailable ?? null) : null,
225→      returnPolicy: widgetConfig?.showReturnPolicy !== false ? (zipRecord.returnPolicy ?? null) : null,
226→      showWaitlist: false,
227→      waitlistCount: 0,
228→      cutoffTime: matchedRule?.cutoffTime ?? null,
229→      daysOfWeek: matchedRule?.daysOfWeek ?? null,
230→    }),
231→    { status: 200, headers: SUCCESS_HEADERS },
232→  );
233→}
234→
235→// Handle GET requests: ?shop=...&zip=...
236→export const loader = async ({ request }: LoaderFunctionArgs) => {
237→  const url = new URL(request.url);
238→
239→  // Handle CORS preflight
240→  if (request.method === "OPTIONS") {
241→    return new Response(null, { status: 204, headers: CORS_HEADERS });
242→  }
243→
244→  const shop = url.searchParams.get("shop");
245→  const zip = url.searchParams.get("zip");
246→  return handleZipCheck(shop, zip);
247→};
248→
249→// Handle POST requests with JSON body: { shop, zip }
250→export const action = async ({ request }: ActionFunctionArgs) => {
251→  let shop: string | null = null;
252→  let zip: string | null = null;
253→
254→  try {
255→    const body = await request.json();
256→    shop = body?.shop ?? null;
257→    zip = body?.zip ?? null;
258→  } catch {
259→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
260→      status: 400,
261→      headers: CORS_HEADERS,
262→    });
263→  }
264→
265→  return handleZipCheck(shop, zip);
266→};
