  4→ * Called from the theme app extension block when a zip code check fails and
  5→ * the merchant has enabled the waitlist feature.
  6→ *
  7→ * POST /api/waitlist
  8→ * Body: { shop: string, zip: string, email: string }
  9→ *
 10→ * Response:
 11→ *   200 { success: true, message: "..." }
 12→ *   400 { error: "..." }
 13→ *   500 { error: "..." }
 14→ */
 15→import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→import { getShopSubscription } from "../billing.server";
 18→
 19→/**
 20→ * Normalize postal/zip code for multi-format international support.
 21→ * Handles: US ZIP+4, UK postcodes, Indian pincodes, Australian postcodes, Canadian postal codes.
 22→ */
 23→function normalizeZipCode(raw: string): string {
 24→  let z = raw.trim().toUpperCase();
 25→  z = z.replace(/\s+/g, "");        // collapse all internal spaces (UK: SW1A 2AA → SW1A2AA)
 26→  z = z.replace(/-\d{4}$/, "");     // strip US ZIP+4 suffix (90210-1234 → 90210)
 27→  return z;
 28→}
 29→
 30→const CORS_HEADERS = {
 31→  "Access-Control-Allow-Origin": "*",
 32→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 33→  "Access-Control-Allow-Headers": "Content-Type",
 34→  "Content-Type": "application/json",
 35→};
 36→
 37→// Handle CORS preflight
 38→export const loader = async ({ request }: LoaderFunctionArgs) => {
 39→  if (request.method === "OPTIONS") {
 40→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 41→  }
 42→  return new Response(JSON.stringify({ error: "Method not allowed" }), {
 43→    status: 405,
 44→    headers: CORS_HEADERS,
 45→  });
 46→};
 47→
 48→export const action = async ({ request }: ActionFunctionArgs) => {
 49→  if (request.method === "OPTIONS") {
 50→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 51→  }
 52→
 53→  if (request.method !== "POST") {
 54→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 55→      status: 405,
 56→      headers: CORS_HEADERS,
 57→    });
 58→  }
 59→
 60→  let shop: string | null = null;
 61→  let zip: string | null = null;
 62→  let email: string | null = null;
 63→
 64→  try {
 65→    const body = await request.json();
 66→    shop = body?.shop ?? null;
 67→    zip = body?.zip ?? null;
 68→    email = body?.email ?? null;
 69→  } catch {
 70→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
 71→      status: 400,
 72→      headers: CORS_HEADERS,
 73→    });
 74→  }
 75→
 76→  if (!shop || !zip || !email) {
 77→    return new Response(
 78→      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
 79→      { status: 400, headers: CORS_HEADERS },
 80→    );
 81→  }
 82→
 83→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 84→  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
 85→    return new Response(
 86→      JSON.stringify({ error: "Invalid shop parameter" }),
 87→      { status: 400, headers: CORS_HEADERS },
 88→    );
 89→  }
 90→
 91→  // Enforce input length limits to prevent abuse
 92→  if (zip.length > 20 || email.length > 254) {
 93→    return new Response(
 94→      JSON.stringify({ error: "Invalid input" }),
 95→      { status: 400, headers: CORS_HEADERS },
 96→    );
 97→  }
 98→
 99→  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
100→    return new Response(
101→      JSON.stringify({ error: "Invalid email address" }),
102→      { status: 400, headers: CORS_HEADERS },
103→    );
104→  }
105→
106→  // Check if shop's plan allows waitlist
107→  try {
108→    const subscription = await getShopSubscription(shop);
109→    if (subscription.limits.maxWaitlist === 0) {
110→      return new Response(
111→        JSON.stringify({ error: "Waitlist is not available on this store's plan" }),
112→        { status: 400, headers: CORS_HEADERS },
113→      );
114→    }
115→    // Enforce entry limit for Starter plan
116→    if (subscription.limits.maxWaitlist !== Infinity) {
117→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
118→      if (currentCount >= subscription.limits.maxWaitlist) {
119→        return new Response(
120→          JSON.stringify({ error: "Waitlist is currently full. Please try again later." }),
121→          { status: 400, headers: CORS_HEADERS },
122→        );
123→      }
124→    }
125→  } catch {
126→    // Non-fatal — allow waitlist signup if subscription check fails
127→  }
128→
129→  try {
130→    await db.waitlistEntry.upsert({
131→      where: {
132→        shop_email_zipCode: {
133→          shop,
134→          email,
135→          zipCode: normalizeZipCode(zip),
136→        },
137→      },
138→      create: {
139→        shop,
140→        email,
141→        zipCode: normalizeZipCode(zip),
142→        status: "waiting",
143→      },
144→      update: {
145→        status: "waiting",
146→      },
147→    });
148→
149→    return new Response(
150→      JSON.stringify({
151→        success: true,
152→        message: "You've been added to the waitlist!",
153→      }),
154→      { status: 200, headers: CORS_HEADERS },
155→    );
156→  } catch {
157→    return new Response(
158→      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
159→      { status: 500, headers: CORS_HEADERS },
160→    );
161→  }
162→};
