  1→import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
  2→import { useLoaderData, useNavigate, useRevalidator } from "react-router";
  3→import { authenticate } from "../shopify.server";
  4→import { boundary } from "@shopify/shopify-app-react-router/server";
  5→import db from "../db.server";
  6→import { getShopSubscription } from "../billing.server";
  7→import { PLAN_LIMITS } from "../plans";
  8→import {
  9→  Page,
 10→  Card,
 11→  BlockStack,
 12→  InlineStack,
 13→  Text,
 14→  Badge,
 15→  Button,
 16→  Banner,
 17→  InlineGrid,
 18→  ProgressBar,
 19→  Box,
 20→  Divider,
 21→  List,
 22→} from "@shopify/polaris";
 23→import { PlusIcon } from "@shopify/polaris-icons";
 24→
 25→export const loader = async ({ request }: LoaderFunctionArgs) => {
 26→  const { session } = await authenticate.admin(request);
 27→  const shop = session.shop;
 28→
 29→  const zipCodes = await db.zipCode.findMany({ where: { shop } });
 30→  const [deliveryRulesCount, waitlistCount, subscription] = await Promise.all([
 31→    db.deliveryRule.count({ where: { shop } }),
 32→    db.waitlistEntry.count({ where: { shop } }),
 33→    getShopSubscription(shop),
 34→  ]);
 35→
 36→  const stats = {
 37→    total: zipCodes.length,
 38→    allowed: zipCodes.filter((z) => z.type === "allowed").length,
 39→    blocked: zipCodes.filter((z) => z.type === "blocked").length,
 40→    deliveryRules: deliveryRulesCount,
 41→    waitlist: waitlistCount,
 42→  };
 43→
 44→  // Detect whether the App Embed is enabled in the active theme
 45→  let appEmbedEnabled = false;
 46→  let activeThemeName: string | null = null;
 47→  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
 48→  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;
 49→
 50→  try {
 51→    const themesRes = await fetch(
 52→      `https://${shop}/admin/api/2026-01/themes.json?role=main`,
 53→      { headers: { "X-Shopify-Access-Token": session.accessToken ?? "" } },
 54→    );
 55→    if (themesRes.ok) {
 56→      const themesJson = (await themesRes.json()) as {
 57→        themes?: { id: number; name: string }[];
 58→      };
 59→      const mainTheme = themesJson.themes?.[0];
 60→      if (mainTheme) {
 61→        const numericId = String(mainTheme.id);
 62→        activeThemeName = mainTheme.name;
 63→        themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
 64→        themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;
 65→
 66→        const assetRes = await fetch(
 67→          `https://${shop}/admin/api/2026-01/themes/${numericId}/assets.json?asset%5Bkey%5D=config%2Fsettings_data.json`,
 68→          { headers: { "X-Shopify-Access-Token": session.accessToken ?? "" } },
 69→        );
 70→        if (assetRes.ok) {
 71→          const assetJson = (await assetRes.json()) as {
 72→            asset?: { value?: string };
 73→          };
 74→          const content = assetJson?.asset?.value;
 75→          if (content) {
 76→            const settingsData = JSON.parse(content) as {
 77→              current?: { blocks?: Record<string, unknown> };
 78→            };
 79→            const blocks = settingsData?.current?.blocks ?? {};
 80→            // Block keys/types in settings_data.json look like:
 81→            // shopify://apps/<handle>/blocks/app_embed/<uuid>
 82→            // Only match our app using the SHOPIFY_API_KEY (client_id)
 83→            const apiKey = process.env.SHOPIFY_API_KEY ?? "";
 84→            appEmbedEnabled = Object.entries(blocks).some(
 85→              ([key, block]) => {
 86→                const b = block as { type?: string; disabled?: boolean };
 87→                const typeStr = b.type ?? "";
 88→                const isAppEmbed =
 89→                  typeStr.includes("app-embed") ||
 90→                  typeStr.includes("app_embed");
 91→                if (!isAppEmbed || b.disabled === true) return false;
 92→                // Only match our specific app by API key (client_id)
 93→                // This avoids false positives from other apps or deleted apps
 94→                if (apiKey && (key.includes(apiKey) || typeStr.includes(apiKey))) {
 95→                  return true;
 96→                }
 97→                return false;
 98→              },
 99→            );
100→          }
101→        }
102→      }
103→    }
104→  } catch {
105→    // Non-fatal — embed status defaults to false
106→  }
107→
108→  return {
109→    stats,
110→    subscription,
111→    appEmbedEnabled,
112→    activeThemeName,
113→    themeEditorUrl,
114→    themeEditorAppEmbedsUrl,
115→  };
116→};
